def _safe_file_stem(value: str, fallback: str = "DevelopAid") -> str:
    stem = re.sub(r"[^0-9A-Za-zА-Яа-яЁё _-]+", "_", str(value or "")).strip(" _")
    return (stem[:60] or fallback)


