def _field_meta() -> dict[str, tuple[str, str]]:
    """Названия и единицы вводных — из того же справочника, что рисует форму."""
    meta: dict[str, tuple[str, str]] = {}
    for _, fields in FIELD_GROUPS:
        for item in fields:
            meta[str(item[0])] = (str(item[1]), str(item[2]))
    return meta


